svg.script:
(() => {
    "use strict";
    const XHTML = "http://www.w3.org/1999/xhtml";
    document.title = "Eaglercraft";
    const app = document.getElementById("app");

    const hash = decodeURIComponent(
        location.hash.slice(1)
    );

    const createElement = (tag, text = "", attributes = {}) => {
        const el = document.createElementNS(XHTML, tag);

        for (const [key, value] of Object.entries(attributes)) {
            el.setAttribute(key, value);
        }

        if (text !== null && text !== undefined) {
            el.textContent = text;
        }

        return el;
    };

    const formatBytes = bytes => {
        if (!Number.isFinite(bytes) || bytes <= 0) {
            return "0 B";
        }

        const units = ["B", "KB", "MB", "GB", "TB"];
        const i = Math.min(
            Math.floor(Math.log(bytes) / Math.log(1024)),
            units.length - 1
        );

        return `${parseFloat(
            (bytes / 1024 ** i).toFixed(2)
        )} ${units[i]}`;
    };

    const progressPercent = (downloaded, total) => {
        if (!total) return null;
        return Math.min(100, downloaded / total * 100);
    };

    const fetchFile = async (url, onProgress) => {
        const response = await fetch(url);

        if (!response.ok) {
            throw new Error(
                `${url}: HTTP ${response.status} ${response.statusText}`
            );
        }

        if (!response.body) {
            throw new Error(`${url}: Response has no body`);
        }

        const total =
            Number(response.headers.get("content-length")) || 0;

        let downloaded = 0;
        const chunks = [];

        const reader = response.body.getReader();

        while (true) {
            const { done, value } = await reader.read();

            if (done) break;

            chunks.push(value);
            downloaded += value.byteLength;

            onProgress?.(downloaded, total);
        }

        return new Blob(chunks);
    };

    const fetchClient = async (
        client,
        onProgressPerFile,
        onProgress
    ) => {
        const urls = client.files.map(
            file => `parts/${file}`
        );

        const progress = urls.map(() => ({
            downloaded: 0,
            size: 0,
            status: "pending"
        }));

        const updateProgress = () => {
            for (let index = 0; index < urls.length; index++) {
                const file = progress[index];

                if (!file || file.downloaded <= 0) {
                    progress[index].status = "pending";
                } else if (file.size > 0 && file.downloaded >= file.size) {
                    progress[index].status = "done";
                } else {
                    progress[index].status = "downloading";
                }
            }

            const downloadedTotal = progress.reduce(
                (sum, file) => sum + file.downloaded,
                0
            );

            const sizeTotal = progress.reduce(
                (sum, file) => sum + file.size,
                0
            );

            const percent = progressPercent(
                downloadedTotal,
                sizeTotal
            );

            if (percent !== null) {
                document.title =
                    `Downloading... (${percent.toFixed(1)}%)`;
            } else {
                document.title =
                    `Downloading... (${formatBytes(downloadedTotal)})`;
            }

            onProgress?.(
                downloadedTotal,
                sizeTotal,
                progress
            );
        };

        const promises = urls.map((url, index) => {
            const fileElement = createElement(
                "pre",
                "",
                {
                    style:
                        "margin:4px 0;white-space:pre-wrap"
                }
            );

            app.append(fileElement);

            return fetchFile(
                url,
                (downloaded, size) => {
                    progress[index] = {
                        downloaded,
                        size
                    };

                    const percent =
                        progressPercent(downloaded, size);

                    fileElement.textContent =
                        (percent === null
                            ? `[${formatBytes(downloaded)}]`
                            : `[${percent.toFixed(1)}%]` +
                            ` ${url} ` +
                              `(${formatBytes(downloaded)} / ` +
                              `${formatBytes(size)})` +
                              ` - ${progress[index]?.status || "pending"}`);

                    onProgressPerFile?.(
                        index,
                        downloaded,
                        size
                    );

                    updateProgress();
                }
            ).catch(error => {
                progress[index].status = "error";
                throw error;
            }).finally(() => {
                progress[index].status = "done";
                fileElement.remove();
            });
        });

        return Promise.all(promises);
    };

    const loadConfig = async () => {
        const response = await fetch("config.json");

        if (!response.ok) {
            throw new Error(
                `config.json: HTTP ${response.status}`
            );
        }

        return response.json();
    };

    const launchClient = async client => {
        console.log(
            `Loading client: ${client.name}`,
            client
        );

        const clientText = createElement("pre", `Downloading ${client.name}...`);
        app.append(clientText);

        const parts = await fetchClient(
            client,
            (index, downloaded, size) => {
                console.log(
                    `[${index + 1}/${client.files.length}]`,
                    formatBytes(downloaded),
                    size
                        ? `/ ${formatBytes(size)}`
                        : ""
                );
            },
            (downloaded, size, statuses) => {
                const percent =
                    progressPercent(downloaded, size);

                if (percent !== null) {
                    const finished = statuses.filter(s => s.status === "done").length;
                    clientText.textContent =
                        `[${finished}/${client.files.length}]` + 
                        ` ${client.name} ` +
                        `(${formatBytes(downloaded)} / ` +
                        `${formatBytes(size)})`
                    console.log(
                        `Overall: ${percent.toFixed(2)}% ` +
                        `(${formatBytes(downloaded)} / ` +
                        `${formatBytes(size)})`
                    );
                }
            }
        );

        const htmlBlob = new Blob(parts, {
            type: "text/html"
        });

        const url = URL.createObjectURL(htmlBlob);

        location.href = url;
    };

    const renderClientList = clients => {
        app.replaceChildren();

        app.append(
            createElement(
                "h1",
                "Eaglercrafts:"
            ),

            createElement("hr")
        );

        const list = createElement("ul");

        for (const client of Object.values(clients)) {
            const item = createElement("li");

            const link = createElement(
                "a",
                client.name,
                {
                    href: `#${encodeURIComponent(
                        client.hashname
                    )}`
                }
            );

            link.addEventListener("click", async event => {
                event.preventDefault();

                history.pushState(
                    null,
                    "",
                    `#${encodeURIComponent(
                        client.hashname
                    )}`
                );

                try {
                    app.replaceChildren();

                    app.append(
                        createElement(
                            "b",
                            `Loading ${client.name}...`
                        )
                    );

                    await launchClient(client);
                } catch (error) {
                    console.error(error);

                    app.replaceChildren();

                    app.append(
                        createElement(
                            "b",
                            "Failed to load client"
                        ),
                        createElement(
                            "pre",
                            String(error)
                        )
                    );
                }
            });

            item.append(link);
            list.append(item);
        }

        app.append(list);
    };

    (async () => {
        try {
            const config = await loadConfig();
            const clients = config.clients;

            if (!clients) {
                throw new Error(
                    "config.json does not contain a 'clients' object"
                );
            }

            if (hash) {
                const client = Object.values(clients)
                    .find(
                        c => c.hashname === hash
                    );

                if (!client) {
                    throw new Error(
                        `Client '${hash}' was not found`
                    );
                }

                await launchClient(client);
            } else {
                renderClientList(clients);
            }

        } catch (error) {
            console.error(error);

            app.replaceChildren(
                createElement(
                    "h1",
                    "Eaglercraft loader error"
                ),
                createElement(
                    "pre",
                    String(error)
                )
            );
        }
    })();
})();
